func TestPrepareTranscript_NonTransientStatError(t *testing.T) {
	t.Parallel()

	// Broken symlinks cause os.Stat to return a non-IsNotExist error.
	tmpDir := t.TempDir()
	path := filepath.Join(tmpDir, "broken-link.jsonl")

	if err := os.Symlink("/nonexistent/target", path); err != nil {
		t.Skipf("cannot create symlink: %v", err)
	}

	ag := &CursorAgent{}
	err := ag.PrepareTranscript(context.Background(), path)
	if err == nil {
		t.Fatal("expected error for broken symlink, got nil")
	}
	if !strings.Contains(err.Error(), "failed to stat transcript") {
		t.Errorf("expected 'failed to stat transcript' error, got: %v", err)
	}
}

